int processArray(int arr[5],int size,int mask){int totalSum;int i;int j;int num;int result;int masked;int isPrime;totalSum=0;for(i=0;i<size;i=i+1){num=arr[i];result=0;if((num&0xAAAAAAAA)==0xAAAAAAAA){result=result+num;}if((num&0x55555555)==0){result=result+(num>>1);}masked=num&mask;if(masked>1){isPrime=1;for(j=2;j*j<=masked;j=j+1){if(masked%j==0){isPrime=0;break;}}if(isPrime!=0){result=result+masked;}}totalSum=totalSum+result;if(i>0){if((arr[i]&arr[i-1])==0){totalSum=totalSum+arr[i];}}if((arr[i]>>2)==mask){totalSum=totalSum+arr[i]*2;}}return totalSum;return;}
